// i18n.js : every word the player reads, in Malay, English and Russian. Shared by the app and the bot.
export const LANGS = ['ms', 'en', 'ru'];
export const LANG_NAME = { ms: 'Bahasa Melayu', en: 'English', ru: 'Русский' };
const I = { ms: 0, en: 1, ru: 2 };
// Telegram language_code -> our language. Russian-speaking locales get Russian, Malay/Indonesian get Malay, the rest English.
export const langFrom = code => { const c = String(code || '').slice(0, 2).toLowerCase(); return ['ru', 'uk', 'be', 'kk', 'ky', 'uz'].includes(c) ? 'ru' : ['ms', 'id'].includes(c) ? 'ms' : c ? 'en' : 'ms'; };

