const BY_MS = new Map(Object.entries(D).map(([k, v]) => [v[0], k]));
const fill = (s, v) => s.replace(/\{(\w+)\}/g, (_, x) => v[x] ?? '');
export const tr = (lang, k, v = {}) => { const e = D[k]; return e ? fill(e[I[lang] ?? 0] ?? e[0], v) : k; };
// Text that arrives already in Malay (match banners from the engine, item tags, perks) -> current language.
export const trMs = (lang, s) => {
  if (!s || lang === 'ms') return s;
  const k = BY_MS.get(s); if (k) return tr(lang, k);
  let m = /^(\d+) TENDANGAN HABIS$/.exec(s); if (m) return tr(lang, 'taps_out', { n: m[1] });
  const BN = { 'PENALTI': 'pen_round', 'MATI MENGEJUT': 'sudden', 'SELAMAT!': 'saved', 'TERLEPAS': 'missed', 'TIANG!': 'woodwork', 'Gol terbalik, sepakan gol': 'wood_s' };
  if (BN[s]) return tr(lang, BN[s]);
  m = /^JIMAT (\d+%)$/.exec(s); if (m) return tr(lang, 'tag_save', { n: m[1] });
  return s;
};
export const itemName = (it, lang) => (lang !== 'ms' && IT[it?.id]?.[I[lang] - 1]?.[0]) || it?.name || '';
export const itemDesc = (it, lang) => (lang !== 'ms' && IT[it?.id]?.[I[lang] - 1]?.[1]) || it?.desc || '';
export const KEYS = Object.keys(D), ITEM_IDS = Object.keys(IT); // for tests
